function reviewPack(theme) {
  return PLAYER_AGENT_ROLES.map((role, index) => ({
    role,
    severity: 'P3',
    scores: Object.fromEntries(SCORE_KEYS.map((key) => [key, key === 'copyClarity' || index % 4 === 0 ? 5 : 4])),
    notes: role + ' pass: ' + theme + ' uses modelable topic facts, distinct facets, and concise player-facing reveals.',
  }));
}

function q(prompt, answer, funFact, rationale, extra) {
  return {
    prompt,
    answer,
    funFact,
    rationale,
    answerType: extra.answerType,
    sources: [extra.source],
    answerNote: extra.answerNote,
    difficultyScore: extra.difficultyScore,
    scaleBand: extra.scaleBand,
    themeKey: extra.themeKey,
    questionKey: extra.questionKey,
    estimationMode: extra.estimationMode,
    calibrationAnchor: extra.calibrationAnchor,
    questionMove: extra.questionMove,
    anchorType: extra.anchorType,
    topicFacet: extra.topicFacet,
    iconicExact: extra.iconicExact === true,
    agentDifficultyTarget: extra.agentDifficultyTarget,
    asOfDate: '2026-05-23',
    rebuiltPrompt: true,
  };
}

function pack(theme, playability, questions, extraInning = null) {
  return {
    id: theme.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''),
    theme,
    playability,
    themeKey: theme.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''),
    rebuiltPack: true,
    editorialStatus: 'launch_ready',
    playerAgentSignoff: [...PLAYER_AGENT_ROLES],
    playerAgentReviews: reviewPack(theme),
    playerAgentFindings: [],
    questions,
    ...(extraInning ? { extraInning } : {}),
  };
}

function reservePack(reserveId, theme, playability, questions, extraInning = null) {
  return {
    ...pack(theme, playability, questions, extraInning),
    id: reserveId,
    reserveId,
  };
}

